    "Evden uzakta": "Longe de casa", // EN: Away from home
    "Evden \u00c7\u0131k\u0131\u015f": "Saindo de casa", // EN: Leaving Home
    "Evden \u00c7\u0131k\u0131\u015f Kontrol\u00fc": "Saindo de casa", // EN: Leaving Home Check
